<?php
declare(strict_types=1);
namespace DigiForge\Portal;
use DigiForge\Database\Tables;
use WP_Error;
/** Append-only versioned shop/workflow policy evidence. Saving policy is not execution authorization. */
final class ScopedCapabilityPolicyRepository {
 public function append(string $shop,string $workflow,string $capability,bool $enabled):array|WP_Error {
  $access=\DigiForge\Security\ShopAccess::authorize($shop,'manage_digiforge');if($access instanceof WP_Error)return $access;
  global $wpdb;$shop=sanitize_key($shop);$workflow=sanitize_key($workflow);$capability=sanitize_key($capability);if($shop===''||$workflow===''||$capability==='')return new WP_Error('invalid_scoped_policy','Shop, workflow and capability are required.');
  $state=null;$prev=$this->latest($shop,$workflow,$capability,$state);if($state!=='AVAILABLE')return new WP_Error('scoped_policy_predecessor_unavailable','Scoped policy predecessor evidence is unavailable.');$version=is_array($prev)?((int)$prev['policy_version']+1):1;$previous=is_array($prev)?(string)$prev['policy_hash']:'';
  $canonical=wp_json_encode(['shop_key'=>$shop,'workflow_key'=>$workflow,'capability'=>$capability,'enabled'=>$enabled,'policy_version'=>$version,'previous_policy_hash'=>$previous]);$hash=hash('sha256',(string)$canonical);$now=current_time('mysql',true);
  $ok=$wpdb->insert(Tables::scoped_capability_policies(),['shop_key'=>$shop,'workflow_key'=>$workflow,'capability'=>$capability,'enabled'=>$enabled?1:0,'policy_version'=>$version,'policy_hash'=>$hash,'previous_policy_hash'=>$previous,'created_by'=>get_current_user_id(),'created_at'=>$now]);if($ok!==1)return new WP_Error('scoped_policy_persistence_failed','Scoped policy evidence could not be persisted.');
  return ['id'=>(int)$wpdb->insert_id,'shop_key'=>$shop,'workflow_key'=>$workflow,'capability'=>$capability,'enabled'=>$enabled,'policy_version'=>$version,'policy_hash'=>$hash,'previous_policy_hash'=>$previous,'read_only_evidence'=>true,'external_execution_authorized'=>false];
 }
 public function latest(string $shop,string $workflow,string $capability, ?string &$queryState=null):?array {global $wpdb;$wpdb->last_error='';$r=$wpdb->get_row($wpdb->prepare('SELECT id,shop_key,workflow_key,capability,enabled,policy_version,policy_hash,previous_policy_hash,created_by,created_at FROM '.Tables::scoped_capability_policies().' WHERE shop_key=%s AND workflow_key=%s AND capability=%s ORDER BY policy_version DESC LIMIT 1',sanitize_key($shop),sanitize_key($workflow),sanitize_key($capability)),ARRAY_A);if(!empty($wpdb->last_error)){$queryState='UNAVAILABLE';return null;}$queryState='AVAILABLE';if(!is_array($r))return null;if(!$this->valid($r)){$queryState='UNAVAILABLE';return null;}$r['read_only_evidence']=true;$r['external_execution_authorized']=false;return $r;}
 /** Bounded read-only policy history; newest first. */
 public function recent(string $shop='',string $workflow='',int $limit=50, ?string &$queryState=null):array {global $wpdb;$limit=max(1,min(200,$limit));$where=[];$args=[];if($shop==='')$where[]="BINARY shop_key IN ('digital','personalized_pod','standard_pod','jewelry')";if($shop!==''){$where[]='shop_key=%s';$args[]=sanitize_key($shop);}if($workflow!==''){$where[]='workflow_key=%s';$args[]=sanitize_key($workflow);}$sql='SELECT id,shop_key,workflow_key,capability,enabled,policy_version,policy_hash,previous_policy_hash,created_by,created_at FROM '.Tables::scoped_capability_policies().($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC LIMIT %d';$args[]=$limit;$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare($sql,...$args),ARRAY_A);if(!is_array($rows)||!empty($wpdb->last_error)){$queryState='UNAVAILABLE';return [];}foreach($rows as $row){if(!$this->valid($row)){$queryState='UNAVAILABLE';return [];}}$queryState='AVAILABLE';return array_map(static function(array $r):array{$r['read_only_evidence']=true;$r['retry_permitted']=false;$r['external_execution_authorized']=false;return $r;},$rows);}
 public function current(int $limit=100, ?string &$queryState=null,string $shop=''):array {global $wpdb;$limit=max(1,min(200,$limit));$table=Tables::scoped_capability_policies();$sql="SELECT p.id,p.shop_key,p.workflow_key,p.capability,p.enabled,p.policy_version,p.policy_hash,p.previous_policy_hash,p.created_by,p.created_at FROM $table p INNER JOIN (SELECT shop_key,workflow_key,capability,MAX(policy_version) latest_version FROM $table GROUP BY shop_key,workflow_key,capability) x ON p.shop_key=x.shop_key AND p.workflow_key=x.workflow_key AND p.capability=x.capability AND p.policy_version=x.latest_version ORDER BY p.shop_key,p.workflow_key,p.capability LIMIT %d";if($shop!==''){$sql=str_replace(' ORDER BY p.shop_key', ' WHERE p.shop_key=%s ORDER BY p.shop_key',$sql);$args=[sanitize_key($shop),$limit];}else{$sql=str_replace(' ORDER BY p.shop_key'," WHERE BINARY p.shop_key IN ('digital','personalized_pod','standard_pod','jewelry') ORDER BY p.shop_key",$sql);$args=[$limit];}$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare($sql,...$args),ARRAY_A);if(!is_array($rows)||!empty($wpdb->last_error)){$queryState='UNAVAILABLE';return [];}foreach($rows as $row){if(!$this->valid($row)){$queryState='UNAVAILABLE';return [];}}$queryState='AVAILABLE';return array_map(static function(array $r):array{$r['read_only_evidence']=true;$r['external_execution_authorized']=false;return $r;},$rows);}
 private function valid(array $r,int $depth=0):bool {
  if($depth>=1000)return false;$version=(int)($r['policy_version']??0);$enabled=$r['enabled']??null;
  if($version<1||!in_array($enabled,[0,1,'0','1'],true))return false;
  foreach(['shop_key','workflow_key','capability'] as $key)if(!is_string($r[$key]??null)||$r[$key]===''||sanitize_key($r[$key])!==$r[$key])return false;
  $previous=(string)($r['previous_policy_hash']??'');if(($version===1&&$previous!=='')||($version>1&&!preg_match('/^[a-f0-9]{64}$/D',$previous)))return false;
  $canonical=wp_json_encode(['shop_key'=>$r['shop_key'],'workflow_key'=>$r['workflow_key'],'capability'=>$r['capability'],'enabled'=>(int)$enabled===1,'policy_version'=>$version,'previous_policy_hash'=>$previous]);
  if(!is_string($canonical)||!hash_equals(hash('sha256',$canonical),(string)($r['policy_hash']??'')))return false;
  if($version>1){global $wpdb;$wpdb->last_error='';$prior=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::scoped_capability_policies().' WHERE shop_key=%s AND workflow_key=%s AND capability=%s AND policy_version=%d',$r['shop_key'],$r['workflow_key'],$r['capability'],$version-1),ARRAY_A);if($wpdb->last_error!==''||!is_array($prior)||!hash_equals($previous,(string)$prior['policy_hash'])||!$this->valid($prior,$depth+1))return false;}
  return true;
 }
}